def _try_to_get_filename(obj):
    """
    Try to get file name from given path or file object.

    :param obj: a file, file-like object or something
    :return: File name or None

    >>> _try_to_get_filename("a.py")
    'a'
    """
    if hasattr(obj, "name"):
        return os.path.basename(obj.name)
    elif isinstance(obj, str):
        return os.path.basename(obj)
    else:
        return None


